INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8201, 'ទំហំ \(y\) និង \(x\) សមាមាត្រស្រប នោះទំនាក់ទំនងគឺ៖', NULL, '["\\(y = a + x\\)", "\\(y = \\dfrac{a}{x}\\)", "\\(y = ax\\)", "\\(xy = a\\)"]', 2, NULL, 1, 'mcq', 'សមាមាត្រស្រប \(\dfrac{y}{x} = a\) ឬ \(y = ax\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'easy', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8202, 'ក្នុងចំនួន \(x\) និង \(y\) ដែល \(xy = 36\) បើ \(x = 4\) នោះ \(y\) ស្មើ៖', NULL, '["\\(144\\)", "\\(9\\)", "\\(40\\)", "\\(32\\)"]', 1, NULL, 1, 'mcq', '\(y = \dfrac{36}{4} = 9\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'easy', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
