INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8203, 'ចតុកោណកែងពីរមានផ្ទៃក្រឡាស្មើគ្នា \(36\ \text{m}^2\)។ ចតុកោណកែងទីពីរមានទទឹង \(6\ \text{m}\) បណ្តោយ៖', 'g8-a9bbc67c0d.svg', '["\\(6\\ \\text{m}\\)", "\\(216\\ \\text{m}\\)", "\\(9\\ \\text{m}\\)", "\\(30\\ \\text{m}\\)"]', 0, NULL, 1, 'mcq', '\(6 \times 6 = 36\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'easy', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
