INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8210, 'ពិន័យសៀវភៅសងយឺត \(100\) ៛ មួយថ្ងៃ។ ពិន័យ \(y\) ក្នុង \(x\) ថ្ងៃគឺ៖', NULL, '["\\(y = 100 - x\\)", "\\(y = 100x\\)", "\\(y = x + 100\\)", "\\(y = \\dfrac{100}{x}\\)"]', 1, NULL, 1, 'mcq', 'ប្រាក់ពិន័យសមាមាត្រស្របនឹងចំនួនថ្ងៃ។', 'ទំហំសមាមាត្រនិងភាគរយ', 'easy', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8211, 'សៀវភៅសរសេរ \(4\) ក្បាល ថ្លៃ \(3\,600\) ៛ (តម្លៃម្នាក់ៗដូចគ្នា)។ \(10\) ក្បាល ថ្លៃប៉ុន្មាន?', NULL, '["\\(4\\,600\\) ៛", "\\(3\\,600\\) ៛", "\\(9\\,600\\) ៛", "\\(9\\,000\\) ៛"]', 3, NULL, 2, 'mcq', '\(\dfrac{3\,600}{4} \times 10 = 9\,000\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8212, 'គេឱ្យ \(a : b = 5 : 18\) និង \(a + b = 138\)។ តម្លៃនៃ \(b\) គឺ៖', NULL, '["\\(30\\)", "\\(108\\)", "\\(113\\)", "\\(120\\)"]', 1, NULL, 2, 'mcq', '\(\dfrac{a}{5} = \dfrac{b}{18} = \dfrac{138}{23} = 6\) ដូចនេះ \(b = 18 \times 6 = 108\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8213, 'កម្មករ \(35\) នាក់សង់ផ្ទះហើយក្នុង \(16\) ថ្ងៃ។ កម្មករ \(28\) នាក់សង់ក្នុងរយៈពេលប៉ុន្មានថ្ងៃ?', NULL, '["\\(20\\) ថ្ងៃ", "\\(12.8\\) ថ្ងៃ", "\\(13\\) ថ្ងៃ", "\\(19\\) ថ្ងៃ"]', 0, NULL, 2, 'mcq', '\(28x = 35 \times 16\) នាំឱ្យ \(x = 20\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
