INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8220, 'សៀវភៅសរសេរ \(8\) ក្បាល ថ្លៃ \(12\,000\) ៛ (តម្លៃម្នាក់ៗដូចគ្នា)។ \(5\) ក្បាល ថ្លៃប៉ុន្មាន?', NULL, '["\\(8\\,100\\) ៛", "\\(12\\,000\\) ៛", "\\(12\\,500\\) ៛", "\\(7\\,500\\) ៛"]', 3, NULL, 2, 'mcq', '\(\dfrac{12\,000}{8} \times 5 = 7\,500\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8221, 'គេឱ្យ \(a : b = 3 : 5\) និង \(a + b = 200\)។ តម្លៃនៃ \(b\) គឺ៖', NULL, '["\\(128\\)", "\\(75\\)", "\\(125\\)", "\\(195\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{a}{3} = \dfrac{b}{5} = \dfrac{200}{8} = 25\) ដូចនេះ \(b = 5 \times 25 = 125\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8222, 'ប៊ីដុង \(4\) ចាក់ទឹកពេញអាងអស់ \(70\) នាទី។ ប៊ីដុង \(7\) ចាក់ពេញអស់ប៉ុន្មាននាទី?', NULL, '["\\(49\\) នាទី", "\\(40\\) នាទី", "\\(122.5\\) នាទី", "\\(63\\) នាទី"]', 1, NULL, 2, 'mcq', '\(7x = 4 \times 70\) នាំឱ្យ \(x = 40\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
