INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8223, 'ដីរាងចតុកោណកែងមួយមានផ្ទៃក្រឡា \(\mathcal{A} = 36\ \text{m}^2\) ទទឹង \(4\ \text{m}\)។ បណ្តោយ \(y\) ស្មើ៖', 'g8-154386b468.svg', '["\\(32\\ \\text{m}\\)", "\\(9\\ \\text{m}\\)", "\\(144\\ \\text{m}\\)", "\\(18\\ \\text{m}\\)"]', 1, NULL, 2, 'mcq', '\(xy = 36\) នាំឱ្យ \(y = \dfrac{36}{4} = 9\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8224, 'ទិញរថយន្ត \(84\,000\)$ លក់ \(60\,000\)$។ ភាគរយប្រាក់ខាត (ធៀបថ្លៃដើម)៖', NULL, '["\\(71.43\\%\\)", "\\(24\\%\\)", "\\(40\\%\\)", "\\(28.57\\%\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{24\,000}{84\,000} \times 100\% \approx 28.57\%\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8225, 'រកតម្លៃ \(x\) បើ \(4 : 7 = x : 5\)៖', NULL, '["\\(\\dfrac{28}{5}\\)", "\\(\\dfrac{7}{20}\\)", "\\(\\dfrac{20}{7}\\)", "\\(\\dfrac{35}{4}\\)"]', 2, NULL, 3, 'mcq', '\(7x = 4 \times 5\) នាំឱ្យ \(x = \dfrac{20}{7}\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8226, 'គេឱ្យ \(a : b : c = 7 : 13 : 20\) និង \(a + b + c = 520\)។ តម្លៃនៃ \(a, b, c\) គឺ៖', NULL, '["\\(91,\\ 169,\\ 260\\)", "\\(70,\\ 130,\\ 200\\)", "\\(91,\\ 169,\\ 240\\)", "\\(104,\\ 169,\\ 247\\)"]', 0, NULL, 3, 'mcq', '\(\dfrac{520}{7+13+20} = 13\) ; \(7 \times 13 = 91\) ; \(13 \times 13 = 169\) ; \(20 \times 13 = 260\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8227, 'កម្មករ \(25\) នាក់ ធ្វើការ \(26\) ម៉ោង ផលិតស្បែកជើង \(1\,300\) គូ។ កម្មករ \(25\) នាក់ដដែល ត្រូវធ្វើការប៉ុន្មានម៉ោងដើម្បីផលិត \(450\) គូ?', NULL, '["\\(75\\) ម៉ោង", "\\(26\\) ម៉ោង", "\\(9\\) ម៉ោង", "\\(4.5\\) ម៉ោង"]', 2, NULL, 3, 'mcq', '\(\dfrac{26}{1\,300} \times 450 = 9\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8228, 'តាមរូប ចតុកោណកែងទី ១ មានបណ្តោយ \(6\ \text{cm}\) ទទឹង \(4\ \text{cm}\)។ ចតុកោណកែងទី ៣ សមាមាត្រនឹងរូបទី ១ មានបណ្តោយ \(15\ \text{cm}\)។ ទទឹង \(y\) គឺ៖', 'g8-7ba511ad78.svg', '["\\(9\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(22.5\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{6}{4} = \dfrac{15}{y}\) នាំឱ្យ \(y = 10\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8229, 'ពូសុខទិញចម្ការ \(2\,240\,000\) ៛ ហើយលក់ខាត \(22\%\)។ ថ្លៃលក់វិញគឺ៖', NULL, '["\\(492\\,800\\) ៛", "\\(2\\,732\\,800\\) ៛", "\\(2\\,239\\,978\\) ៛", "\\(1\\,747\\,200\\) ៛"]', 3, NULL, 3, 'mcq', '\(2\,240\,000 \times 0.78 = 1\,747\,200\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8230, 'អាវធំមួយបញ្ចុះតម្លៃ \(15\%\) នៅសល់ \(846\,000\) ៛។ តម្លៃដើមប្រហែល (ទសភាគ ២ ខ្ទង់) គឺ៖', NULL, '["\\(846\\,015\\) ៛", "\\(719\\,100\\) ៛", "\\(995\\,294.12\\) ៛", "\\(972\\,900\\) ៛"]', 2, NULL, 3, 'mcq', '\(\dfrac{846\,000}{0.85} = 995\,294.12\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8231, 'ក្រោយដំឡើង \(8\%\) ប្រាក់ខែលោកស្រីចាន់ធីជា \(518\,400\) ៛។ ប្រាក់ខែដើមគឺ៖', NULL, '["\\(477\\,000\\) ៛", "\\(466\\,560\\) ៛", "\\(480\\,000\\) ៛", "\\(559\\,872\\) ៛"]', 2, NULL, 3, 'mcq', '\(\dfrac{100}{108} \times 518\,400 = 480\,000\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8232, 'ម៉ាស៊ីនត្រជាក់ថ្លៃ \(2\,700\,000\) ៛ បង់កក់ \(20\%\) ប្រាក់ជំពាក់ថែមការប្រាក់ \(10\%\) ក្នុងមួយឆ្នាំ រយៈពេល \(48\) ខែ។ សងរំលស់ប្រចាំខែ (ជារៀល)៖', NULL, '["\\(63\\,000\\) ៛", "\\(45\\,000\\) ៛", "\\(67\\,500\\) ៛", "\\(56\\,250\\) ៛"]', 0, NULL, 3, 'mcq', '\(2\,700\,000 - 540\,000 = 2\,160\,000\) ; \(I = 2\,160\,000 \times 0.1 \times 4 = 864\,000\) ; \(\dfrac{3\,024\,000}{48} = 63\,000\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8233, 'ម៉ាស៊ីនបោកខោអាវថ្លៃ \(1\,350\,000\) ៛ កក់ \(15\%\) ។ ប្រាក់កក់គឺ៖', NULL, '["\\(20\\,250\\) ៛", "\\(1\\,147\\,500\\) ៛", "\\(135\\,000\\) ៛", "\\(202\\,500\\) ៛"]', 3, NULL, 3, 'mcq', '\(0.15 \times 1\,350\,000 = 202\,500\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8234, 'បណ្ណាល័យមានសៀវភៅប្រលោមលោក \(28\%\) ហើយសៀវភៅមិនមែនប្រលោមលោកច្រើនជាង \(1\,980\) ក្បាល។ សៀវភៅសរុបមាន៖', NULL, '["\\(1\\,980\\) ក្បាល", "\\(3\\,240\\) ក្បាល", "\\(7\\,071\\) ក្បាល", "\\(4\\,500\\) ក្បាល"]', 3, NULL, 3, 'mcq', '\(72\% - 28\% = 44\%\) ; \(\dfrac{1\,980}{0.44} = 4\,500\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8235, 'សាំងតម្លៃ \(3\,750\) ៛ ក្នុងមួយលីត្រ ចាក់ពេញធុង \(112\,500\) ៛។ បើសាំងឡើង \(210\) ៛ ក្នុងមួយលីត្រ ចាក់ពេញធុងអស់៖', NULL, '["\\(118\\,800\\) ៛", "\\(119\\,250\\) ៛", "\\(112\\,710\\) ៛", "\\(7\\,560\\) ៛"]', 0, NULL, 3, 'mcq', '\(\dfrac{112\,500}{3\,750} = 30\) លីត្រ ; \(30 \times 3\,960 = 118\,800\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8236, 'មីងសានចែកប្រាក់ឱ្យកូន \(3\) នាក់អាយុ \(14, 16, 18\) ឆ្នាំ តាមសមាមាត្រនឹងអាយុ។ អ្នកអាយុ \(14\) ឆ្នាំ ទទួល \(105\,000\) ៛។ ប្រាក់ទាំងអស់៖', NULL, '["\\(120\\,000\\) ៛", "\\(315\\,000\\) ៛", "\\(240\\,000\\) ៛", "\\(360\\,000\\) ៛"]', 3, NULL, 3, 'mcq', '\(\dfrac{105\,000}{14} = 7\,500\) ; \(48 \times 7\,500 = 360\,000\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8237, 'ក. រកតម្លៃ \(x\) បើ \(4 : 7 = x : 5\)។ ខ. គេឱ្យ \(a : b = 5 : 18\) និង \(a + b = 138\) រកតម្លៃ \(b\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(7x = 4 \times 5 = 20\) (1 ពិន្ទុ)
\(x = \dfrac{20}{7}\) (1 ពិន្ទុ)
ខ. \(\dfrac{a}{5} = \dfrac{b}{18} = \dfrac{138}{23} = 6\) (2 ពិន្ទុ)
\(b = 18 \times 6 = 108\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'easy', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8238, 'ក. រកតម្លៃ \(x\) បើ \(x : 8 = 99 : 5\)។ ខ. រកតម្លៃ \(x\) បើ \(1\ \text{km} : 32\ \text{m} = 250\ \text{g} : x\ \text{g}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(5x = 8 \times 99 = 792\) (1 ពិន្ទុ)
\(x = 158.4\) (1 ពិន្ទុ)
ខ. \(1\ \text{km} = 1\,000\ \text{m}\) (1 ពិន្ទុ)
\(1\,000x = 32 \times 250 = 8\,000\) (1 ពិន្ទុ)
\(x = 8\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8239, 'ក. គេឱ្យ \(a : b : c = 7 : 13 : 20\) និង \(a + b + c = 520\) រក \(a, b, c\)។ ខ. គេឱ្យ \(a : b : c = 4 : 6 : 9\) និង \(b - a = 34\ \text{m}\) រក \(a + b + c\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{a}{7} = \dfrac{b}{13} = \dfrac{c}{20} = \dfrac{520}{40} = 13\) (1 ពិន្ទុ)
\(a = 91,\ b = 169,\ c = 260\) (2 ពិន្ទុ)
ខ. \(\dfrac{b - a}{6 - 4} = \dfrac{34}{2} = 17\) (1 ពិន្ទុ)
\(a + b + c = 19 \times 17 = 323\ \text{m}\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8240, 'កម្មករ \(35\) នាក់សង់ផ្ទះហើយក្នុង \(16\) ថ្ងៃ។ ក. ចំនួនកម្មករនិងចំនួនថ្ងៃជាទំហំសមាមាត្រអ្វី? ខ. កម្មករ \(28\) នាក់សង់ក្នុងប៉ុន្មានថ្ងៃ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. សមាមាត្រច្រាស ព្រោះកម្មករកើនថ្ងៃថយ (1 ពិន្ទុ)
ខ. \(28x = 35 \times 16\) (2 ពិន្ទុ)
\(x = \dfrac{560}{28} = 20\) ថ្ងៃ (2 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8241, 'កាកបាទក្រហមផ្តល់អង្ករ \(320\ \text{kg}\) ឱ្យ \(3\) គ្រួសារមានសមាជិក \(4, 5, 7\) នាក់ ដោយចំណែកសមាមាត្រនឹងចំនួនសមាជិក។ រកចំណែកនីមួយៗ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(a, b, c\) ជាចំណែក ; \(\dfrac{a}{4} = \dfrac{b}{5} = \dfrac{c}{7}\) (1 ពិន្ទុ)
\(= \dfrac{a+b+c}{4+5+7} = \dfrac{320}{16} = 20\) (2 ពិន្ទុ)
\(a = 80,\ b = 100,\ c = 140\ \text{kg}\) (2 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8242, 'កម្មការិនី \(12\) នាក់ធ្វើការ \(7\) ម៉ោងក្នុងមួយថ្ងៃ បញ្ចប់ការងារក្នុង \(8\) ថ្ងៃ។ កម្មការិនី \(16\) នាក់ត្រូវធ្វើការប៉ុន្មានម៉ោងក្នុងមួយថ្ងៃ ដើម្បីបញ្ចប់ការងារក្នុង \(16\) ថ្ងៃ?', NULL, '[]', 0, NULL, 5, 'writing', 'ការងារសរុប \(12 \times 7 \times 8 = 672\) ម៉ោង-កម្មការិនី (2 ពិន្ទុ)
\(16 \times h \times 16 = 672\) (1 ពិន្ទុ)
\(h = \dfrac{672}{256} = \dfrac{21}{8}\) (1 ពិន្ទុ)
\(= 2\dfrac{5}{8}\) ម៉ោង (២ ម៉ោង ៣៧.៥ នាទី) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8243, 'ក្រុមហ៊ុនទិញរថយន្តមួយ \(75\,000\) ដុល្លារ លក់ឱ្យលោកស្រីស៊ុន \(84\,000\) ដុល្លារ។ លោកស្រីលក់បន្ត \(60\,000\) ដុល្លារ។ ក. រកភាគរយប្រាក់ចំណេញរបស់ក្រុមហ៊ុន។ ខ. រកភាគរយប្រាក់ខាតរបស់លោកស្រីស៊ុន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ប្រាក់ចំណេញ \(84\,000 - 75\,000 = 9\,000\) (1 ពិន្ទុ)
\(\dfrac{9\,000}{75\,000} \times 100\% = 12\%\) (1 ពិន្ទុ)
ខ. ប្រាក់ខាត \(84\,000 - 60\,000 = 24\,000\) (1 ពិន្ទុ)
\(\dfrac{24\,000}{84\,000} \times 100\%\) (1 ពិន្ទុ)
\(\approx 28.57\%\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8244, 'ក. រកការប្រាក់សមាសលើ \(1\,800\,000\) ៛ រយៈពេល \(2\) ឆ្នាំ អត្រា \(10\%\) បន្ថែមលើប្រាក់ដើមរាល់ឆ្នាំ។ ខ. ប្រៀបធៀបជាមួយការប្រាក់សាមញ្ញ។', NULL, '[]', 0, NULL, 5, 'writing', 'ឆ្នាំទី ១ ៖ \(1\,800\,000 \times 10\% = 180\,000\) (1 ពិន្ទុ)
ប្រាក់ដើមថ្មី \(1\,980\,000\) ; ឆ្នាំទី ២ ៖ \(198\,000\) (1 ពិន្ទុ)
ការប្រាក់សមាស \(180\,000 + 198\,000 = 378\,000\) ៛ (1 ពិន្ទុ)
ការប្រាក់សាមញ្ញ \(\dfrac{1\,800\,000 \times 10 \times 2}{100} = 360\,000\) ៛ (1 ពិន្ទុ)
ការប្រាក់សមាសច្រើនជាង \(18\,000\) ៛ (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8245, 'រកការប្រាក់សមាសលើ \(2\,800\,000\) ៛ រយៈពេល \(3\) ឆ្នាំ អត្រា \(11\%\) បន្ថែមលើប្រាក់ដើមរាល់ឆ្នាំ។', NULL, '[]', 0, NULL, 5, 'writing', 'ឆ្នាំទី ១ ៖ \(2\,800\,000 \times 0.11 = 308\,000\) (1 ពិន្ទុ)
ឆ្នាំទី ២ ៖ \(3\,108\,000 \times 0.11 = 341\,880\) (1 ពិន្ទុ)
ឆ្នាំទី ៣ ៖ \(3\,449\,880 \times 0.11 = 379\,486.8\) (1 ពិន្ទុ)
\(308\,000 + 341\,880 + 379\,486.8\) (1 ពិន្ទុ)
\(= 1\,029\,366.8\) ៛ (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'hard', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8246, 'ពូភាទិញម៉ាស៊ីនត្រជាក់ \(2\,700\,000\) ៛ បង់កក់ \(20\%\) ប្រាក់ជំពាក់ថែមការប្រាក់ \(10\%\) ក្នុងមួយឆ្នាំ រយៈពេល \(48\) ខែ។ ក. រកប្រាក់កក់និងប្រាក់ជំពាក់។ ខ. រកការប្រាក់ និងសងរំលស់ប្រចាំខែ។ គ. បើទិញសងភ្លាម សន្សំបានប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ប្រាក់កក់ \(20\% \times 2\,700\,000 = 540\,000\) (1 ពិន្ទុ)
ប្រាក់ជំពាក់ \(2\,700\,000 - 540\,000 = 2\,160\,000\) (1 ពិន្ទុ)
ខ. \(I = \dfrac{2\,160\,000 \times 10 \times 4}{100} = 864\,000\) (1 ពិន្ទុ)
សងរំលស់ \(\dfrac{2\,160\,000 + 864\,000}{48} = 63\,000\) ៛ (1 ពិន្ទុ)
គ. សន្សំបាន \(864\,000\) ៛ (ការប្រាក់) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-8048b731b8.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8247, 'រូបខាងក្រោមបង្ហាញចម្ការបី។ ផ្ទៃក្រឡាសមាមាត្រនឹង \(12 : 49 : 28\) ហើយសរុប \(2\ \text{ha}\ 67\ \text{a}\) (\(1\ \text{ha} = 100\ \text{a}\), \(1\ \text{a} = 100\ \text{m}^2\))។ ក. គណនាផ្ទៃក្រឡានីមួយៗ។ ខ. ចម្ការទី ១ រាងការេ រកជ្រុង។ គ. ចម្ការទី ២ បណ្តោយ \(3\) ដងទទឹង រកវិមាត្រ។ ឃ. ចម្ការទី ៣ វិមាត្រសមាមាត្រ \(7 : 3\) រកវិមាត្រ។', 'g8-8048b731b8.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(26\,700 \div 89 = 300\) ; \(\mathcal{A}_1 = 3\,600,\ \mathcal{A}_2 = 14\,700,\ \mathcal{A}_3 = 8\,400\ \text{m}^2\) (1 ពិន្ទុ)
ខ. \(\sqrt{3\,600} = 60\ \text{m}\) (1 ពិន្ទុ)
គ. \(3w^2 = 14\,700 \Rightarrow w = 70\) ; បណ្តោយ \(210\ \text{m}\) (1 ពិន្ទុ)
ឃ. \(7t \times 3t = 21t^2 = 8\,400 \Rightarrow t = 20\) (1 ពិន្ទុ)
វិមាត្រ \(140\ \text{m} \times 60\ \text{m}\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8248, 'ម៉ាស៊ីនបោកខោអាវថ្លៃ \(1\,350\,000\) ៛ ទិញបង់រំលស់ កក់ \(15\%\) ប្រាក់ជំពាក់អត្រា \(10\dfrac{2}{3}\%\) ក្នុងមួយឆ្នាំ រយៈពេល \(2\) ឆ្នាំ សងជា \(24\) ខែ។ ក. រកប្រាក់កក់និងប្រាក់ជំពាក់។ ខ. រកការប្រាក់ និងសងរំលស់ប្រចាំខែ។ គ. រកភាគរយប្រាក់បន្ថែមធៀបថ្លៃសងភ្លាម។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. កក់ \(202\,500\) ; ជំពាក់ \(1\,147\,500\) (1 ពិន្ទុ)
ខ. \(I = 1\,147\,500 \times \dfrac{32}{3} \times \dfrac{1}{100} \times 2 = 244\,800\) (1 ពិន្ទុ)
\(\dfrac{1\,147\,500 + 244\,800}{24} = 58\,012.5 \approx 58\,013\) ៛ (1 ពិន្ទុ)
គ. \(\dfrac{244\,800}{1\,350\,000} \times 100\%\) (1 ពិន្ទុ)
\(\approx 18.13\%\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8249, 'រូបបង្ហាញចតុកោណកែងបីសមាមាត្រគ្នា។ រូបទី ១ មានបណ្តោយ \(6\ \text{cm}\) ទទឹង \(4\ \text{cm}\)។ ក. រកផលធៀបបណ្តោយនិងទទឹង។ ខ. រកបណ្តោយ \(x\) នៃរូបទី ២ ដែលទទឹង \(8\ \text{cm}\)។ គ. រកទទឹង \(y\) នៃរូបទី ៣ ដែលបណ្តោយ \(15\ \text{cm}\)។ ឃ. គណនាផ្ទៃក្រឡារូបទី ៣។', 'g8-7ba511ad78.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{6}{4} = \dfrac{3}{2}\) (1 ពិន្ទុ)
ខ. \(\dfrac{3}{2} = \dfrac{x}{8} \Rightarrow x = 12\ \text{cm}\) (1 ពិន្ទុ)
គ. \(\dfrac{3}{2} = \dfrac{15}{y} \Rightarrow y = 10\ \text{cm}\) (1 ពិន្ទុ)
ឃ. \(\mathcal{A} = 15 \times 10\) (1 ពិន្ទុ)
\(= 150\ \text{cm}^2\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8250, 'បណ្ណាល័យមានសៀវភៅប្រលោមលោក \(28\%\) នៃសៀវភៅទាំងអស់ ហើយសៀវភៅមិនមែនប្រលោមលោកច្រើនជាងប្រលោមលោក \(1\,980\) ក្បាល។ ក. រកចំនួនសៀវភៅទាំងអស់។ ខ. រកចំនួនសៀវភៅប្រលោមលោក និងមិនមែនប្រលោមលោក។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មិនមែនប្រលោមលោក \(100\% - 28\% = 72\%\) (1 ពិន្ទុ)
ផលដក \(72\% - 28\% = 44\%\) ត្រូវនឹង \(1\,980\) (1 ពិន្ទុ)
សរុប \(\dfrac{1\,980}{0.44} = 4\,500\) ក្បាល (1 ពិន្ទុ)
ខ. ប្រលោមលោក \(0.28 \times 4\,500 = 1\,260\) (1 ពិន្ទុ)
មិនមែនប្រលោមលោក \(0.72 \times 4\,500 = 3\,240\) (1 ពិន្ទុ)', 'ទំហំសមាមាត្រនិងភាគរយ', 'pisa', 0, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
